def max_product(num_str: str, N: int, K: int) -> int:
    """
    Finds the maximum product of a number string by inserting K multiplication signs.

    :param num_str: A string representing the number string.
    :param N: An integer representing the length of the number string.
    :param K: An integer representing the number of multiplication signs to insert.
    :return: The maximum product of the resulting subarrays.
    """
    from functools import cmp_to_key
    import math

    def compare(a, b):
        return int(b * int(a)) - int(a * int(b))

    def max_product_helper(num_str, K):
        if K == 0:
            return int(num_str)
        max_prod = 0
        for i in range(1, N):
            prod = max_product_helper(num_str[:i], K - 1) * int(num_str[i:])
            max_prod = max(max_prod, prod)
        return max_prod

    return max_product_helper(num_str, K)

